    const CardProyect = ({ content, title, img, imgPos, link, technologies }) => {
        const [hovered, setHovered] = useState(false);
        return (
            <>
                <a
                    href={link}
                    target="_blank"
                    className={`project-card ${hovered ? 'hovered' : ''}`}
                    onMouseEnter={() => setHovered(true)}
                    onMouseLeave={() => setHovered(false)}
                >

                    <img className="project-card-image" style={{ objectPosition: imgPos || 'left' }} src={img} alt="" />

                    <div className="project-card-body">

                        <h3 className="project-card-title">{title}</h3>

                        <p className="project-card-desc">{content}</p>

                        {technologies && technologies.length > 0 && (
                            <div className="project-card-techs">
                                {technologies.map(techId => {
                                    const tech = TECH_DATA[techId];
                                    if (!tech) return null;
                                    return (
                                        <div key={techId} className="project-card-tech-icon" title={tech.name}>
                                            {tech.svg}
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                    </div>

                </a>
            </>
        );
    }

